head.script:
scwin.trigger1_onclick = function(e) {
    var options = {
        id: "popup1",
        type: "window",
        width: "500px",
        height: "400px",
        popupName: "Test",
        modal: false,
        useIFrame: false,
        style: "",
        resizable: true,
        status: false,
        menubar: false,
        scrollbars: false,
        title: false,
        xml: "",
        dataObject: {
            type: "json",
            data: {
                "aa": "11",
                "bb": "11"
            },
            name: "param1"
        },
        srcData: "",
        destData: "",
        closeAction: ""
    };
    $w.openPopup("popup_dataObject_WPF-1715_(WSQ-2891)_Sub.xml", options);
};
scwin.trigger3_onclick = function(e) {
    var options = {
        id: "popup2",
        type: "window",
        width: "500px",
        height: "400px",
        popupName: "Test",
        modal: false,
        useIFrame: false,
        style: "",
        resizable: true,
        status: false,
        menubar: false,
        scrollbars: false,
        title: false,
        xml: "",
        dataObject: {
            type: "json",
            data: {
                "aa": "22",
                "bb": "22"
            },
            name: "param2"
        },
        srcData: "",
        destData: "",
        closeAction: ""
    };
    $w.openPopup("popup_dataObject_WPF-1715_(WSQ-2891)_Sub.xml", options);
};
scwin.__isShowDataOption = function() {
    var arr = JSON.parse(localStorage.getItem("array"));
    console.log(arr);
    return arr[0] != arr[1];
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "2000");
    // Test step 1. 샘플파일을 실행하여 popup별로 dataObject가 값에 맞게 전달되는지를 확인한다.
    //1. Run the sample file to see if the dataObject is passed by value for each popup.
    WebSquare.wUnit.addCommand("assert", "scwin.__isShowDataOption()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    requires("uiplugin.popup");;
    scwin.trigger1_onclick();
    scwin.trigger3_onclick();
    //Function unitTest
    //Created By: Sang.do
    //Created By: 09-Mar-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
